<?php
defined('ABSPATH') || exit;
/** Read-only administrator diagnostics. Never imports, approves or grants access. */
final class CAFCC_Diagnostics {
    public static function init(){add_action('admin_menu',function(){add_submenu_page('cafcc','Getting started & diagnostics','Getting started','manage_options','cafcc-diagnostics',array(__CLASS__,'screen'));});add_action('rest_api_init',function(){register_rest_route('cafcc/v4','/admin/diagnostics',array('methods'=>'GET','permission_callback'=>function($r){return CAFCC_REST::permission($r,true);},'callback'=>array(__CLASS__,'report')));});}
    public static function report(){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator access required.',403);global $wpdb;$rt=CAFCC_Studio::table();$reviews=(int)$wpdb->get_var("SELECT COUNT(*) FROM $rt");$statuses=$wpdb->get_results("SELECT status,publication_status,COUNT(*) AS records FROM $rt GROUP BY status,publication_status",ARRAY_A);$nodes=CAFCC_DB::table('taxonomy');$ed=CAFCC_DB::table('editions');$count=(int)$wpdb->get_var("SELECT COUNT(*) FROM $nodes n WHERE ".CAFCC_Academic::published('n'));$requests=new WP_REST_Request('GET');$f=CAFCC_Facets::filters($requests);list($from,$where,$args)=CAFCC_Facets::parts($f,get_current_user_id());$eligible=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) $from WHERE $where",$args));$o=CAFCC_DB::table('occurrences');$oc=(int)$wpdb->get_var("SELECT COUNT(*) FROM $o");$sample=$wpdb->get_col("SELECT id FROM $rt ORDER BY id DESC LIMIT 20");$queue=array();foreach($sample as $id){$r=CAFCC_Studio::get($id);$queue[]=array('id'=>(int)$id,'stable_id'=>$r['stable_id'],'publication_status'=>$r['publication_status'],'question_id'=>$r['question_id'],'readiness'=>CAFCC_Studio::readiness($r));}
        return array('scope'=>'This WordPress installation only; offline research files are not discovered or synchronised automatically.','review_records'=>$reviews,'review_states'=>$statuses,'reviewed_published_nodes'=>$count,'connected_occurrences'=>$oc,'eligible_question_records'=>$eligible,'next_action'=>$reviews===0?'Import your private studio-drafts-001.json through Question Review Studio → Import research batch → Validate → Apply.':($eligible===0?'Open a draft in Studio and follow its Next required action; check edition/taxonomy/source, all seven reviews and final publication.':'Question records are eligible for administrator preview. Student access still requires a verified account and current entitlement.'),'recent_review_blockers'=>$queue,'privacy'=>'No source prose, private notes, passwords, tokens or entitlement grants are included.');
    }
    public static function screen(){
        if(!CAFCC_Repository::admin_allowed())wp_die('Administrator access required.');nocache_headers();$r=self::report();echo '<div class="wrap"><h1>Getting started &amp; Question Bank diagnostics</h1><p>This reports the installation you are currently signed into. It cannot inspect offline research files or another WordPress website.</p><h2>Next required action</h2><p><strong>'.esc_html($r['next_action']).'</strong></p><table class="widefat"><tbody>';foreach(array('review_records'=>'Research draft/review rows','reviewed_published_nodes'=>'Published reviewed taxonomy nodes (inspect ancestors too)','connected_occurrences'=>'Connected occurrences, including drafts','eligible_question_records'=>'Eligible question records, administrator preview') as $key=>$label)echo '<tr><th>'.esc_html($label).'</th><td>'.esc_html($r[$key]).'</td></tr>';echo '</tbody></table><h2>How the pieces connect</h2><ol>';
        $steps=array('PDF research output: private offline extraction candidates, coordinates, hashes and corrections. Processing a PDF does not write to WordPress.','Private review package: a downloadable workbook, JSON and evidence for your inspection. Downloading it changes neither WordPress nor academic approval.','WordPress research-draft import: Question Review Studio → upload studio-drafts JSON → preview validation/duplicates/conflicts → Apply. Only this step creates review rows. They remain Draft/Needs Review.','Academic approval: inspect original evidence and applicable historical syllabus. Approve source, boundary/number, classification, answer mapping, rights, question revision and answer revision separately. Tests do not perform your academic review.','Student-visible occurrence: Publish When Eligible is a final eighth decision. The occurrence, source, edition, taxonomy and content revision must remain eligible. Students also require a current access entitlement.');foreach($steps as $step)echo '<li><p>'.esc_html($step).'</p></li>';echo '</ol><h2>Administrator guide</h2><dl>';
        $guide=array('Connected Academic Manager'=>'Manage editions, official modules/chapters/units, editorial topics, source documents and relationships. Verify source dates and applicability before publishing headings. Never map a historical paper to a newer edition by convenience.','Topic Proposals'=>'Preview/import missing proposals as drafts. Inspect each source and parent, correct it, then explicitly review/publish the path in Connected Academic Manager. Draft editorial topics remain private; reviewed headings are available in Browse Syllabus even without questions.','Import private research JSON'=>'Use the five-record FR pilot, not the full private ZIP. Studio import supports 100 records per batch. Preview and Apply are separate. Existing conflicting corrections are held, not overwritten.','Correct tags'=>'Open a Studio row, select the historical edition, search/add the reviewed topic or subtopic and choose its primary path. For a supplied pilot, import its draft hierarchy CSV and use Use proposed draft path. Save Draft; mapping proposals are not approval.','Academic review and publication'=>'Follow Next required action in each panel. Inspect source/boundaries, resolve exceptions and verify the exact answer. Separate approvals retain reviewer/time/revision. An edit withdraws relevant approval/publication. Never claim an unreviewed candidate is verified.','Excel review'=>'Export selected Studio rows. Edit Approval Decisions in Excel, upload the workbook, validate conflicts, then apply deliberately. Only server-issued current workbooks can apply; an offline research workbook is context, not an approval token.','Practice Content & Rights'=>'After the first three reviews, Prepare Draft Reference gives a QID. Attach your independently authored/licensed rich question and solution to that QID, approve those saved revisions, verify the exact solution hash, then complete Studio review. Private PDF prose is not a public content source.','Question Explorer, Dashboard and My Practice'=>'Explorer browses reviewed syllabus and eligible questions independently. Dashboard reports only your own saved activity. My Practice contains your own saved records/bookmarks/revision queue. Answer text is fetched only on Show Answer.','Existing Subscribers'=>'Use Student access to verify identity/email and grant the correct manual entitlement individually. No plugin update grants a membership or changes user IDs automatically.');foreach($guide as $label=>$text)echo '<dt><strong>'.esc_html($label).'</strong></dt><dd><p>'.esc_html($text).'</p></dd>';echo '</dl><h2>Recent review blockers (20 most recent)</h2>';if(!$r['recent_review_blockers'])echo '<p>No WordPress research drafts have been imported yet.</p>';foreach($r['recent_review_blockers'] as $row)echo '<p><a href="'.esc_url(admin_url('admin.php?page=cafcc-studio')).'">'.esc_html($row['stable_id']).'</a> · '.esc_html($row['readiness']['next']['stage']).': '.esc_html($row['readiness']['next']['action']).'</p>';echo '<p>Also check held import batches, source/edition publication and the student’s verified membership if an approved record is hidden. This screen never publishes records or changes student data.</p></div>';
    }
}
